pub fn stats(name: WeaponName, level: i32, ascend: bool) -> Option<(f64, f64)> {
    let index = (level.clamp(1, 90) - 1) as usize;
    let (attack, sub, promoted) = match name {
        WeaponName::HereticsMoltenBlade => (&ATK_0, &SUB_0, &ASCENDED_0),
        WeaponName::Emberwell => (&ATK_0, &SUB_1, &ASCENDED_0),
        WeaponName::NewBough => (&ATK_0, &SUB_2, &ASCENDED_0),
        WeaponName::ForgedByTheGoldenMelody => (&ATK_0, &SUB_0, &ASCENDED_0),
        WeaponName::BladeOfAtonement => (&ATK_1, &SUB_0, &ASCENDED_1),
        WeaponName::Frostbreath => (&ATK_0, &SUB_3, &ASCENDED_0),
        WeaponName::SongOfTheVigil => (&ATK_1, &SUB_4, &ASCENDED_1),
        WeaponName::ClashOfKings => (&ATK_0, &SUB_0, &ASCENDED_0),
        WeaponName::EchoesOfTheHeart => (&ATK_1, &SUB_0, &ASCENDED_1),
        WeaponName::WintersHeavyHeart => (&ATK_0, &SUB_2, &ASCENDED_0),
        WeaponName::JadeVista => (&ATK_0, &SUB_0, &ASCENDED_0),
        WeaponName::CovenantOfFrostAndSnow => (&ATK_0, &SUB_5, &ASCENDED_0),
        WeaponName::BreezeborneRefrain => (&ATK_0, &SUB_0, &ASCENDED_0),
        _ => return None,
    };
    let promoted_index = match level { 20 => Some(0), 40 => Some(1), 50 => Some(2), 60 => Some(3), 70 => Some(4), 80 => Some(5), _ => None };
    let base = if ascend { promoted_index.map(|i| promoted[i]).unwrap_or(attack[index]) } else { attack[index] };
    Some((base, sub[index]))
}
